import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E5%B0%8F%E7%B2%8B%E3%81%AA%E3%82%B9%E3%82%AF%E3%83%AA%E3%83%97%E3%83%88%E8%A8%80%E8%AA%9E%E3%81%8C%E6%AC%B2%E3%81%97%E3%81%84.html","title":"小粋なスクリプト言語が欲しい","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.85,"words":556},"filePathRelative":"小粋なスクリプト言語が欲しい.md"}`),a={name:`小粋なスクリプト言語が欲しい.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="小粋なスクリプト言語が欲しい" tabindex="-1"><a class="header-anchor" href="#小粋なスクリプト言語が欲しい"><span>小粋なスクリプト言語が欲しい</span></a></h1><p>機内書き物。だったけどなんとなくその後もちょこちょこ編集しているページ。<a href="./技術的なメモ.html">技術的なメモ</a></p><p>Android用のシェルみたいな何かが欲しいと思って、<a href="./Starlark.html">Starlark</a>で作ろうか、と思ったが、 <a href="./Starlark.html">Starlark</a>はクラスなどが無い。 小さなコアがあっていろいろその上に作っていく、というモノとは用途が違う。</p><p>luaとかはそういうものと思うが、小粋なシンタックスというのとは随分違うものだ。まぁlua詳しくないからそう思うだけかもしれないが。</p><p><a href="./EmbeddedLang.html">EmbeddedLang</a>に以前いろいろ見たのがあるが、これはC++。Kotlinで使いたい、と思う奴が欲しいな。</p><h2 id="求められる性質" tabindex="-1"><a class="header-anchor" href="#求められる性質"><span>求められる性質</span></a></h2><p>そもそも、そういう用途のスクリプト言語というものが無い気がする。 ここで言う「そういう用途」とはなんだろう？</p><ul><li>実装が小さい <ul><li>メンテが簡単</li><li>jarとかにせず簡単に他のプロジェクトにフォルダごとコピーして組み込める</li></ul></li><li>小粋なシンタックス</li><li>スピードは遅くていい</li><li>コアの機能が小さく、拡張していく最低限のものだけを提供している</li><li>実装言語はGC前提で良い（Kotlinとgolangで作れればいい）</li></ul><p><a href="./Starlark.html">Starlark</a>はかなり近い。だが拡張していくベース言語というものではない。</p><p>言語内DSLを作っていけるような基盤が欲しいんだよな。</p><p>実装が簡単でランタイムはホスト側に大きく依存していて、簡単に他の言語でも再実装出来るようなのが欲しい。</p><p>でも<a href="./Starlark.html">Starlark</a>は改めて学習する必要が無く、広く使われている言語に近いというメリットはあるんだよなぁ。 うーむ、自分で作ってもこれらのメリットは得られない気はする。</p><h2 id="欲しい言語機能" tabindex="-1"><a class="header-anchor" href="#欲しい言語機能"><span>欲しい言語機能</span></a></h2><p>まぁ作るのが現実的かどうかはおいといて、何が欲しいのかをもう少し考えてみよう。</p><p>まず、Androidで使いやすいembed言語が欲しい。だからAndroidのランタイムが使えるので独自にGCとかはしなくていい。 実装は小さくて取り回しが良いのが良い。スピードはいらない。普通にテキストをパースして実行するので良い。</p><p>その気になれば簡単に実装出来るようなのがいい。とりあえずgolangとkotlinで簡単に実装出来る何か。</p><p>Python shではいろいろな付加機能をmethod chainや名前付き引数で提供していて、ああいうのを使いたい。 オプショナルな事をいろいろ簡単に書けて欲しいんだよな。</p><p>うーむ、考えていると何が欲しいのか良く分からなくなってきた。</p><p>まず当面の目的は、<a href="./Starlark.html">Starlark</a>で使い方を工夫すればいいような気もしてきたな。たぶんある機能でうまい事考える事は出来る気がする。</p><p>そしてそういう具体例無しで欲しい言語を考えるのは、たぶんうまくいかない。 うまく行かないのだけれど、なんとなくモヤモヤしたものを書き出してスッキリしておくのはやっておきたい気もするので、以下にはぼんやりとした考えを書き出していきたい。</p><p>関数定義が短く出来る言語がいい。ラムダも短く書ける言語がいい。</p><p>オブジェクトリテラルがJavaScriptみたいに簡単に書ける言語がいい。</p><p>パイプ演算子は欲しい。</p><p>デフォルトは短く呼べるが、オプショナルな要素を追加出来るようになっていて欲しい。</p><p>ユーザーに定義させたものを操作しやすい言語がいい。 例えば定義した関数の引数を調べて、その中身に応じて挙動を変えたい。</p><p>パースも実行も簡単な言語がいい。</p><p>例えば<a href="./FSharp.html">FSharp</a>には、パイプラインの途中で<code>$_</code>を使ったプロパティアクセスがあると関数になる、みたいな機能があるが、ああいう感じの言語が欲しい気がするなぁ。</p><p>型は無くて関数適用はF#的で、中括弧でブロック、中括弧の中に<code>$0</code>とかあるとラムダ式になる、とかでどうだろう？ シェルスクリプト的には<code>$1</code>からか？</p><p><a href="https://docs.swift.org/swift-book/documentation/the-swift-programming-language/closures/" target="_blank" rel="noopener noreferrer">SwiftのClosuresは$0から</a>だな。</p><h2 id="仕様の試行錯誤" tabindex="-1"><a class="header-anchor" href="#仕様の試行錯誤"><span>仕様の試行錯誤</span></a></h2><p>ちょっとそれっぽい仕様を考えてみる。ifとかの制御構造は全部ブロックと関数にする。 ブロックは実行可能配列のようなものとして、けれど中に<code>$0</code>とかあったら関数とする。</p><p>関数はfunでkotlinを真似てみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">fun hoge(a, b) {</span>
<span class="line">  a+b</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ラムダだと以下。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">let hoge = {$0+$1}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>関数呼び出しはどうしようかな？まぁとりあえずF#スタイルにしてみるか。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">hoge 1 2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ブロックはクロージャとしてそれが作られた環境を持つ。だからifなどでブロックを渡したら、呼び出し元のスコープとして評価出来る。</p><p>if文はどうしようかなぁ。遅延評価はブロックのみなら以下みたいな感じか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">if cond { body1 } else { body2 }</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>パースすると以下の呼び出しになる。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ifel(cond, block1, block2)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>いや、別にblockにする、と決めてしまえば、パースさえできれば自動でブロックにするのはやればいいか。</p><p>引数無しのブロックはF#同様にカッコを渡すのかなぁ。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">block1 ()</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>まぁこれでいいか。</p><p>以上から考えられる実装</p><ul><li>すべて関数呼び出しのシンタックスシュガー</li><li>遅延評価は全部ブロックになる</li><li>intなども全部boxingしてオブジェクトに</li></ul><p>まぁこんな感じで、あとはシンタックスをモダンな感じに出来たらいいんじゃないか。</p><p>ってこれだとクラスが無いな。いらないっちゃいらないが。でもAndroidのオブジェクト呼ぶからメソッド呼び出しのノーテーションは必要か。 うーん、いまいちだな。</p><h2 id="ホスト側からの使いやすさを考える" tabindex="-1"><a class="header-anchor" href="#ホスト側からの使いやすさを考える"><span>ホスト側からの使いやすさを考える</span></a></h2><p><a href="./Starlark.html">Starlark</a>の不満としては、呼ぶのが面倒というのがある。 もっと原始的な言語でいいんだよなぁ、と。</p><p>コールスタックはいるし、変数のenvはいるし、途中でRuntime Permissionとかをリクエストする必要があるのでyieldも出来ないとだめだが…って考えていくと、結局継続も必要になって、 やっぱり似たような面倒さにはなってしまうか。</p><h2 id="rhinoはどうだろう" tabindex="-1"><a class="header-anchor" href="#rhinoはどうだろう"><span>Rhinoはどうだろう？</span></a></h2><p><a href="./Rhino.html">Rhino</a>がAndroidから使えて途中でサスペンドもできそうでインタープリタとして動きそうではある。 言語機能としてはフルなJavaScriptに近い（async-awaitが無いが）ので、十分な気がする。</p><p>トランスパイラがあればいいのか？と考えて、ReasonMLと互換のパーサーでも書いてくっつけられないかな？と思い立つ。いいかもしれん。そのうちチャレンジしてみよう。</p>`,56)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};